validator:
function validate(input) {
  const [{ customers = [] }] = input;
  let last = -Infinity;
  for (const [id, name, email] of customers) {
    if (id === null) return 'Every row needs a customer_id.';
    if (id <= last) return 'customer_id must increase from row to row.';
    last = id;
    if (name === null) return 'Every customer needs a name.';
    if (email === null) return 'email cannot be null.';
    if (email !== email.toLowerCase()) return 'email must be lowercase.';
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const names = ['Ella', 'David', 'Zachary', 'Alice', 'Finn', 'Violet', 'Amy', 'Zoe'];
  const emails = ['emily@example.com', 'michael@example.com', 'sarah@example.com', 'john@example.com', 'alice@example.com'];
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const customers = [];
  let id = 0;
  for (let i = 0; i < rows; i++) {
    id += 1 + Math.floor(rand() * 3);
    const email = size === 'small' ? pick(emails) : `user${Math.floor(rand() * 800)}@example.com`;
    customers.push([id, pick(names), email]);
  }
  return [{ customers }];
}
